#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/DISCOVER_AND_HOME.md ]] || { echo 'Run from the repository root after the Windows Discover/Home update.' >&2; exit 1; }
python3 - <<'VISUAL_SCREENS'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/screens/collection_screens.dart': '',
'desktop/hyper_player/lib/screens/stream_screen.dart': '',
'desktop/hyper_player/test/visual_screens_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_1.md': '',
}
for name, value in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(value))
print('Native History, Playlists and Open Stream visual alignment applied. Android unchanged.')
VISUAL_SCREENS
